229	  gemmini_extended_mvin(dram_addr, spad_addr, DIM, DIM)
230	
231	#define gemmini_extended_mvout(dram_addr, spad_addr, cols, rows) \
232	  ROCC_INSTRUCTION_RS1_RS2(XCUSTOM_ACC, dram_addr, ((uint64_t)(rows) << (ADDR_LEN + 16)) | ((uint64_t)(cols) << ADDR_LEN) | (uint64_t)(spad_addr), k_MVOUT)
233	
234	#define gemmini_extended_mvout_spad(dst_addr, dst_stride, src_addr, cols, rows) \
235	  ROCC_INSTRUCTION_RS1_RS2(XCUSTOM_ACC, ((uint64_t)(dst_stride) << 32) | (uint64_t)(dst_addr), ((uint64_t)(rows) << (ADDR_LEN + 16)) | ((uint64_t)(cols) << ADDR_LEN) | (uint64_t)(src_addr), k_MVOUT_SPAD)
236	
237	#define gemmini_mvout_spad(dst_addr, src_addr) \
238	  gemmini_extended_mvout_spad(dst_addr, 1, src_addr, DIM, DIM)
239	
240	#define gemmini_mvout(dram_addr, spad_addr) \
241	  gemmini_extended_mvout(dram_addr, spad_addr, DIM, DIM)
242	
243	// compute
244	#define gemmini_extended_compute_preloaded(A, BD, A_cols, A_rows, BD_cols, BD_rows) \
245	  ROCC_INSTRUCTION_RS1_RS2(XCUSTOM_ACC, ((uint64_t)(A_rows) << (ADDR_LEN + 16)) | ((uint64_t)(A_cols) << ADDR_LEN) | (uint64_t)(A), ((uint64_t)(BD_rows) << (ADDR_LEN + 16)) | ((uint64_t)(BD_cols) << ADDR_LEN) | (uint64_t)(BD), k_COMPUTE_PRELOADED)
246	
247	#define gemmini_extended_compute_accumulated(A, BD, A_cols, A_rows, BD_cols, BD_rows) \
248	  ROCC_INSTRUCTION_RS1_RS2(XCUSTOM_ACC, ((uint64_t)(A_rows) << (ADDR_LEN + 16)) | ((uint64_t)(A_cols) << ADDR_LEN) | (uint64_t)(A), ((uint64_t)(BD_rows) << (ADDR_LEN + 16)) | ((uint64_t)(BD_cols) << ADDR_LEN) | (uint64_t)(BD), k_COMPUTE_ACCUMULATE)
249	
250	#define gemmini_compute_preloaded(A, BD) \
251	  gemmini_extended_compute_preloaded(A, BD, DIM, DIM, DIM, DIM)
252	
253	#define gemmini_compute_accumulated(A, BD) \
254	  gemmini_extended_compute_accumulated(A, BD, DIM, DIM, DIM, DIM)
255	
256	// preload
257	#define gemmini_extended_preload(BD, C, BD_cols, BD_rows, C_cols, C_rows) \
258	  ROCC_INSTRUCTION_RS1_RS2(XCUSTOM_ACC, ((uint64_t)(BD_rows) << (ADDR_LEN + 16)) | ((uint64_t)(BD_cols) << ADDR_LEN) | (uint64_t)(BD), ((uint64_t)(C_rows) << (ADDR_LEN + 16)) | ((uint64_t)(C_cols) << ADDR_LEN) | (uint64_t)(C), k_PRELOAD)
