270	    ROCC_INSTRUCTION_RS1_RS2(XCUSTOM_ACC, \
271	        ((uint64_t)acc_scale_t_to_acc_scale_t_bits((acc_scale_t)sys_acc_scale) << 32) | \
272	        ((uint64_t)(A_stride) << 16) | \
273	        ((uint64_t)(out_mx_fmt) << 14) | \
274	        ((uint64_t)(wgt_mx_fmt) << 12) | \
275	        ((uint64_t)(act_mx_fmt) << 10) | \
276	        ((uint64_t)(B_transpose) << 9) | \
277	        ((uint64_t)(A_transpose) << 8) | \
278	        ((uint64_t)(set_only_strides) << 7) | \
279	        ((uint64_t)(uselut) << 5) | \
280	        ((uint64_t)(sys_act) << 3) | \
281	        ((uint64_t)(dataflow) << 2) | \
282	        CONFIG_EX, \
283	        ((uint64_t)(C_stride) << 48) | (uint64_t)(uint32_t)(sys_shift), \
284	        k_CONFIG)
