428	static void sp_tiled_matmul_os(const elem_t * A, const elem_t * B, const void * D, void * C,
429	        scale_t A_scale_factor, scale_t B_scale_factor, scale_acc_t D_scale_factor,
430	        size_t I, size_t J, size_t K, size_t pad_I, size_t pad_J, size_t pad_K,
431	        size_t A_row_stride, size_t B_row_stride, size_t D_row_stride, size_t C_row_stride,
432	        bool a_transpose, bool b_transpose,
433	        bool full_C, bool low_D,
434	        bool no_bias, bool repeating_bias,
435	        int act,
436	        int a_spad_id, int b_spad_id) {
437	
438	  const uint32_t A_sp_addr_start = 0;
439	  const uint32_t B_sp_addr_start = BANK_NUM * BANK_ROWS - K * J * DIM;
440	  const uint32_t D_sp_addr_start = 1 << (ADDR_LEN-1);
441	  const uint32_t C_sp_addr_start = (3 << (ADDR_LEN-2)) | (full_C << (ADDR_LEN-3));
442	
443	  const int A_blocks = K <= MAX_BLOCK_LEN ? K : MAX_BLOCK_LEN;
444	  const int B_blocks = J <= MAX_BLOCK_LEN ? J : MAX_BLOCK_LEN;
445	  const int D_blocks = J <= MAX_BLOCK_LEN_ACC ? J : MAX_BLOCK_LEN_ACC;
446	
447	  // Move-in D
448	  if (D != NULL && !no_bias) {
449	    const size_t D_stride = repeating_bias ? 0 : D_row_stride * sizeof(acc_t);
450	    gemmini_extended_config_ld(D_stride, D_scale_factor);
451	
452	    for (size_t i = 0; i < I; i++) {
453	      for (size_t j = 0; j < J; j += D_blocks) {
454	        const size_t bias_row = repeating_bias ? 0 : i;
455	        const acc_t * const D_dram_addr = (acc_t *)D + (bias_row * D_row_stride + j)*DIM;
456	
457	        const uint32_t D_sp_addr_acc = D_sp_addr_start + (i*J + j)*DIM;
458	
459	        const size_t blocks = j + D_blocks <= J ? D_blocks : J-j;
460	
461	        const size_t cols = blocks * DIM - (j + blocks >= J ? pad_J : 0);
462	        const size_t rows = DIM - (i == I-1 ? pad_I : 0);
463	
464	        gemmini_extended_mvin(D_dram_addr, D_sp_addr_acc, cols, rows);
465	      }
466	    }
467	  }
468	
469	  // Move-in B
470	  gemmini_extended_config_ld(B_row_stride * sizeof(elem_t), B_scale_factor);
471	  for (size_t j = 0; j < J; j += B_blocks) {
472	    for (size_t k = 0; k < K; k++) {
473	      const elem_t * const B_dram_addr = B + (k*B_row_stride + j)*DIM;
474	      const uint32_t B_sp_addr = B_sp_addr_start + (k*J + j)*DIM;
475	      const size_t blocks = j + B_blocks <= J ? B_blocks : J-j;
476	      const size_t cols = blocks * DIM - (j + blocks >= J ? pad_J : 0);
477	      const size_t rows = DIM - (k == K-1 ? pad_K : 0);
478	      gemmini_extended_mvin(B_dram_addr, B_sp_addr, cols, rows);
479	    }
480	  }
481	
482	  // Move-in A
483	  gemmini_extended_config_ld(A_row_stride * sizeof(elem_t), A_scale_factor);
484	  for (size_t i = 0; i < I; i++) {
485	    for (size_t k = 0; k < K; k += A_blocks) {
486	      const elem_t * const A_dram_addr = A + (i*A_row_stride + k)*DIM;
487	      const uint32_t A_sp_addr = A_sp_addr_start + (i*K + k)*DIM;
488	      const size_t blocks = k + A_blocks <= K ? A_blocks : K-k;
489	      const size_t cols = blocks * DIM - (k + blocks >= K ? pad_K : 0);
490	      const size_t rows = DIM - (i == I-1 ? pad_I : 0);
491	      gemmini_extended_mvin(A_dram_addr, A_sp_addr, cols, rows);
492	    }
493	  }
494	
495	  for (size_t i = 0; i < I; i++) {
496	    for (size_t j = 0; j < J; j++) {
497	      const uint32_t C_sp_addr = C_sp_addr_start + (i*J + j)*DIM;
498	
499	      for (size_t k = 0; k < K; k++) {
500	
501	        const uint32_t A_sp_addr = A_sp_addr_start + (i*K + k)*DIM;
502	        const uint32_t B_sp_addr = B_sp_addr_start + (k*J + j)*DIM;
503	
504	        uint32_t out_sp_addr = k == K-1 ? C_sp_addr : GARBAGE_ADDR;
505	
506	        // If we're not using a bias, then we want to overwrite what's in the
507	        // accumulator, rather than writing over it
508	        int no_bias_new_matrix = no_bias && D != NULL && k == K-1;
509	        if (no_bias_new_matrix) {
510	          out_sp_addr &= ~(1 << (ADDR_LEN-2));
511	        }
512	
513	        const size_t A_cols = DIM - (k == K - 1 ? pad_K : 0);
514	        const size_t A_rows = DIM - (i == I - 1 ? pad_I : 0);
515	        const size_t B_cols = DIM - (j == J - 1 ? pad_J : 0);
516	        const size_t B_rows = DIM - (k == K - 1 ? pad_K : 0);
517	        const size_t C_cols = DIM - (j == J - 1 ? pad_J : 0);
518	        const size_t C_rows = DIM - (i == I - 1 ? pad_I : 0);
519	
520	        gemmini_extended_preload(GARBAGE_ADDR, out_sp_addr, DIM, DIM, C_cols, C_rows);
521	
522	        if (k == 0) { // First iteration
523	          gemmini_extended_compute_preloaded(A_sp_addr, B_sp_addr, A_cols, A_rows, B_cols, B_rows);
524	        } else { // All other iterations
525	          gemmini_extended_compute_accumulated(A_sp_addr, B_sp_addr, A_cols, A_rows, B_cols, B_rows);
526	        }
527	      }
528	    }
529	  }
530	
531	  // Move-out C
532	  if (C != NULL) {
533	    const size_t sizeof_C = full_C ? sizeof(acc_t) : sizeof(elem_t);
534	
535	    for (size_t i = 0; i < I; i++) {
536	      for (size_t j = 0; j < J; j++) {
537	        void * const C_dram_addr = (int8_t*)C + (i*C_row_stride + j)*DIM*sizeof_C;
538	        const uint32_t C_sp_addr = C_sp_addr_start + (i*J + j)*DIM;
